def parse_csv_line(line):
    """Parse a single CSV line into a list of field strings."""
    if line == '':
        return ['']

    fields = []
    i = 0
    n = len(line)

    while True:
        # Check if field is quoted
        if i < n and line[i] == '"':
            # Quoted field
            i += 1  # Skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    # Check for escaped quote (two double quotes)
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        # Closing quote found
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                raise ValueError("Quoted field with no closing quote")

            # After closing quote, must be comma or end of line
            if i < n and line[i] != ',':
                raise ValueError("Expected comma or end of line after closing quote")

            fields.append(''.join(field_chars))

            # Skip comma if present, otherwise we're done
            if i < n and line[i] == ',':
                i += 1
            else:
                break
        else:
            # Unquoted field (could be empty if at comma or end)
            field_chars = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("Double quote in unquoted field")
                field_chars.append(line[i])
                i += 1
            fields.append(''.join(field_chars))

            # Skip comma if present, otherwise we're done
            if i < n and line[i] == ',':
                i += 1
            else:
                break

    return fields


